<?php
if (!defined('WHMCS')) die('Direct access denied');
require_once __DIR__.'/bootstrap.php';require_once __DIR__.'/migrations/V100.php';require_once __DIR__.'/migrations/V110.php';
use CloudHost247\Foundation\Database\MigrationRunner;use CloudHost247\Currency\Migrations\CurrencyInitialMigration;use CloudHost247\Currency\Migrations\CurrencyOperationalMigration;use CloudHost247\Currency\Services\CurrencyRepository;use CloudHost247\Currency\Services\AdminController;
function cloudhost247_currency_config(){return array('name'=>'CloudHost247 Currency','description'=>'Independent exchange-rate providers, history, policies and safe WHMCS rate updates.','version'=>'1.1.0','author'=>'CloudHost247','language'=>'english','fields'=>array());}
function cloudhost247_currency_activate(){try{$a=(new MigrationRunner())->run('cloudhost247_currency',array(new CurrencyInitialMigration(),new CurrencyOperationalMigration()));return array('status'=>'success','description'=>'Currency system installed. Applied: '.($a?implode(', ',$a):'already current'));}catch(\Throwable $e){return array('status'=>'error','description'=>$e->getMessage());}}
function cloudhost247_currency_deactivate(){return array('status'=>'success','description'=>'Data retained. Currency history and configuration remain available; WHMCS financial records were not removed.');}
function cloudhost247_currency_output($vars){$v=(new AdminController(new CurrencyRepository()))->handle();$e=function($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');};echo '<h2>CloudHost247 Currency</h2><p class="alert alert-info">Updates current WHMCS currency rates only. Product prices and historical invoices are never rewritten.</p>';if($v['notice'])echo '<div class="alert alert-success">'.$e($v['notice']).'</div>';if($v['error'])echo '<div class="alert alert-danger">'.$e($v['error']).'</div>';echo '<form method="post" class="form-inline"><input type="hidden" name="token" value="'.$e($v['token']).'"><input type="hidden" name="operation" value="settings"><label>Base currency <input class="form-control" maxlength="3" name="base_currency" value="'.$e($v['settings']['base_currency']??'USD').'"></label> <label>Frequency (minutes) <input class="form-control" type="number" min="15" max="43200" name="update_frequency_minutes" value="'.$e($v['settings']['update_frequency_minutes']??360).'"></label> <button class="btn btn-primary">Save</button></form><hr><form method="post"><input type="hidden" name="token" value="'.$e($v['token']).'"><input type="hidden" name="operation" value="update"><button class="btn btn-success">Update Now</button></form><h3>Providers</h3><table class="table"><tr><th>Provider</th><th>Enabled</th><th>Action</th></tr>';foreach($v['providers'] as $p)echo '<tr><td>'.$e($p->display_name).'</td><td>'.($p->enabled?'Yes':'No').'</td><td><form method="post"><input type="hidden" name="token" value="'.$e($v['token']).'"><input type="hidden" name="operation" value="provider"><input type="hidden" name="provider_key" value="'.$e($p->provider_key).'"><input type="hidden" name="enabled" value="'.($p->enabled?0:1).'"><button class="btn btn-xs btn-default">'.($p->enabled?'Disable':'Enable').'</button></form></td></tr>';echo '</table><h3>Currencies</h3><table class="table table-striped"><tr><th>Code</th><th>Current rate</th><th>Enabled / margin / rounding</th></tr>';foreach($v['currencies'] as $c)echo '<tr><td><strong>'.$e($c->currency_code).'</strong></td><td>'.$e($c->current_rate).'</td><td><form method="post" class="form-inline"><input type="hidden" name="token" value="'.$e($v['token']).'"><input type="hidden" name="operation" value="currency"><input type="hidden" name="id" value="'.$e($c->id).'"><label><input type="checkbox" name="enabled" value="1"'.($c->enabled?' checked':'').'> Enabled</label> <input class="form-control" style="width:90px" type="number" step="0.0001" name="margin_percent" value="'.$e($c->margin_percent).'">% <input class="form-control" style="width:70px" type="number" min="0" max="12" name="precision_digits" value="'.$e($c->precision_digits).'"> <select class="form-control" name="rounding_mode">';foreach(array('nearest','up','down') as $m)echo '<option'.($c->rounding_mode===$m?' selected':'').'>'.$m.'</option>';echo '</select> <button class="btn btn-xs btn-primary">Save</button></form></td></tr>';echo '</table><h3>Current vs previous rates</h3><table class="table"><tr><th>Currency</th><th>Current</th><th>Previous</th><th>Change</th><th>Observed</th></tr>';foreach($v['comparison'] as $c){$change=$c['previous']!==null?(float)$c['current']-(float)$c['previous']:null;echo '<tr><td>'.$e($c['currency_code']).'</td><td>'.$e($c['current']).'</td><td>'.$e($c['previous']).'</td><td>'.$e($change).'</td><td>'.$e($c['observed_at']).'</td></tr>';}echo '</table><h3>Update history</h3><table class="table"><tr><th>ID</th><th>Trigger</th><th>Status</th><th>Base</th><th>Rates</th><th>Started</th><th>Finished / error</th></tr>';foreach($v['history'] as $r)echo '<tr><td>'.$e($r->id).'</td><td>'.$e($r->trigger_type).'</td><td>'.$e($r->status).'</td><td>'.$e($r->base_currency).'</td><td>'.$e($r->rate_count).'</td><td>'.$e($r->started_at).'</td><td>'.$e($r->finished_at).' '.$e($r->error_message).'</td></tr>';echo '</table>';}
